/* From Uiverse.io by Lakshay-art - Tags: animation, minimalist, card, hover, realistic, cartoon, shinchan, boochan */
.__UIV_SCOPE__ .face {
  position: relative;
  width: 300px;
  height: 350px;
  background-color: #6C757D;
  background: linear-gradient(180deg,#452824 184px,#f2bbad 34px);
    /* transform: translateX(0px); */
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  border-bottom-left-radius: 250px 250px;
  border-bottom-right-radius: 250px 250px;
  border: 5px solid black;
}

.__UIV_SCOPE__ .hairs {
  height: 180px;
  background-color: #f2bbad;
  position: absolute;
  width: 290px;
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  top: 25px;
}

.__UIV_SCOPE__ .snow {
  transform: translateX(150px);
  transform-origin: right;
}

.__UIV_SCOPE__ .mountain-cap-1, .__UIV_SCOPE__ .mountain-cap-2, .__UIV_SCOPE__ .mountain-cap-3, .__UIV_SCOPE__ .mountain-cap-4 {
  position: absolute;
  top: 20px;
  border-left: 20px solid transparent;
  border-right: 20px solid transparent;
  border-top: 40px solid #452824;
}

.__UIV_SCOPE__ .mountain-cap-1 {
  left: -65px;
}

.__UIV_SCOPE__ .mountain-cap-2 {
  left: -35px;
}

.__UIV_SCOPE__ .mountain-cap-3 {
  left: -5px;
}

.__UIV_SCOPE__ .mountain-cap-4 {
  left: 25px;
}

.__UIV_SCOPE__ .earL {
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  border-bottom-left-radius: 250px 250px;
  border-bottom-right-radius: 250px 250px;
  height: 70px;
  width: 50px;
  background-color: #f2bbad;
  position: absolute;
  left: -30px;
  top: 150px;
  z-index: -1;
  border: 5px solid black;
}

.__UIV_SCOPE__ .earR {
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  border-bottom-left-radius: 250px 250px;
  border-bottom-right-radius: 250px 250px;
  height: 70px;
  width: 50px;
  background-color: #f2bbad;
  position: absolute;
  right: -30px;
  top: 150px;
  z-index: -4;
  border: 5px solid black;
}

.__UIV_SCOPE__ .eyeR {
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  border-bottom-left-radius: 250px 250px;
  border-bottom-right-radius: 250px 250px;
  height: 10px;
  width: 10px;
  background-color: black;
  position: absolute;
  left: 128px;
  top: 120px;
  z-index: 2;
  animation: blinkR 5s infinite linear;
}

.__UIV_SCOPE__ .eyeL {
  border-top-right-radius: 250px 350px;
  border-top-left-radius: 250px 350px;
  border-bottom-left-radius: 250px 250px;
  border-bottom-right-radius: 250px 250px;
  height: 10px;
  width: 10px;
  background-color: black;
  position: absolute;
  right: 128px;
  top: 120px;
  z-index: 2;
  animation: blinkL 5s infinite linear;
}

.__UIV_SCOPE__ .nose {
  background: #fefefe;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  color: #0F0;
  position: absolute;
  top: 220px;
  left: 140px;
  scale: 1 1;
  transition: all ease-in-out .3s;
  z-index: 100;
}

.__UIV_SCOPE__ .nose:hover {
  scale: 1 1.25;
  top: 236px;
}

.__UIV_SCOPE__ .nose:active {
  animation: propeller .5s infinite linear;
  transform-origin: 50% -55px;
  scale: 1 1.25;
  top: 220px;
  animation-delay: .5s;
}

@keyframes propeller {
  to {
    transform: rotateZ(360deg);
  }
}

@keyframes blinkL {
  98% {
    height: 10px;
    width: 10px;
    right: 128px;
    top: 120px;
  }

  100% {
    height: 3px;
    width: 11px;
    right: 126px;
    top: 123px;
  }
}

@keyframes blinkR {
  98% {
    height: 10px;
    width: 10px;
    left: 128px;
    top: 120px;
  }

  100% {
    height: 3px;
    width: 11px;
    left: 126px;
    top: 123px;
  }
}

.__UIV_SCOPE__ .nose:before {
  content: "";
  position: absolute;
  top: -64px;
  left: 50%;
  border: 10px solid transparent;
  border-bottom: 62px solid #fefefe;
  transform: translateX(-50%);
}

.__UIV_SCOPE__ .mouth {
  position: absolute;
  top: 300px;
  left: 140px;
  background: #a36655;
  width: 25px;
  height: 18px;
  border: 5px solid black;
  border-radius: 50%;
  transition: all .3s linear;
}

.__UIV_SCOPE__ .face:active .mouth {
  top: 290px;
  width: 60px;
  height: 25px;
  left: 123px;
  border-radius: 7px 7px 130px 130px;
}

.__UIV_SCOPE__ .face:active .smileL {
  height: 30px;
  width: 30px;
}

.__UIV_SCOPE__ .face:active .smileR {
  height: 30px;
  width: 30px;
}

.__UIV_SCOPE__ .bo {
  z-index: 10;
  zoom: 0.8;
}

.__UIV_SCOPE__ .smileL {
  position: absolute;
  height: 0px;
  width: 0px;
  rotate: 310deg;
  top: 180px;
  left: 70px;
  transition: all .1s linear;
}

.__UIV_SCOPE__ .smileR {
  position: absolute;
  height: 0px;
  width: 0px;
  rotate: 310deg;
  top: 180px;
  right: 70px;
  transition: all .1s linear;
}
